            "locator": "https://clrd.ninjal.ac.jp/unidic_archive/2512/unidic-cwj-202512.zip#sys.dic@169018155",
            "attribution": "National Institute for Japanese Language and Linguistics; modified BSD license",
            "patterns": [
              0
            ],
