            "locator": "https://clrd.ninjal.ac.jp/unidic_archive/2512/unidic-cwj-202512.zip#sys.dic@154916741",
            "attribution": "National Institute for Japanese Language and Linguistics; modified BSD license",
            "patterns": [
              1
            ],
            "finding": "Exact whole 全治/ゼンチ; lemma 全治; 名詞/普通名詞/サ変可能/*; *; *; aType 1.",
