            "locator": "https://clrd.ninjal.ac.jp/unidic_archive/2512/unidic-cwj-202512.zip#sys.dic@272897775",
            "attribution": "National Institute for Japanese Language and Linguistics; modified BSD license",
            "patterns": [
              0
            ],
            "finding": "Exact whole 容易/ヨウイ; lemma 容易; 形状詞/一般/*/*; *; *; aType 0.",
